import org.jfree.chart.util.ObjectUtilities;
import org.jfree.data.general.Series;
import org.jfree.data.general.SeriesChangeEvent;
import org.jfree.data.general.SeriesException;
import org.jfree.data.time.RegularTimePeriod;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for TimeSeries.clone().
 */
public class TimeSeries_clone_TriageGen2Test {







    @Test
    public void testCloneProperties() throws CloneNotSupportedException {
        TimeSeries series = new TimeSeries("Test Series");
        series.setDomainDescription("Domain Desc");
        series.setRangeDescription("Range Desc");
        series.setMaximumItemCount(100);

        TimeSeries clonedSeries = (TimeSeries) series.clone();

        assertEquals("Domain description should be copied", series.getDomainDescription(), clonedSeries.getDomainDescription());
        assertEquals("Range description should be copied", series.getRangeDescription(), clonedSeries.getRangeDescription());
        assertEquals("Maximum item count should be copied", series.getMaximumItemCount(), clonedSeries.getMaximumItemCount());
    }


}
